// Fetch the last 7 days of earthquakes from USGS (no API key needed)
const url = 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_week.geojson';
const res = await fetch(url);
const data = await res.json();

const quakes = data.features.map(f => ({
  mag: f.properties.mag,
  place: f.properties.place,
  time: new Date(f.properties.time).toISOString(),
  depth: f.geometry.coordinates[2],
  lon: f.geometry.coordinates[0],
  lat: f.geometry.coordinates[1],
})).filter(q => q.mag !== null && q.mag >= 0);

nb.set('quakes', quakes);
console.log(`Fetched ${quakes.length} earthquakes from the past 7 days`);
console.log(`Magnitude range: ${Math.min(...quakes.map(q => q.mag)).toFixed(1)} – ${Math.max(...quakes.map(q => q.mag)).toFixed(1)}`);
({ total: quakes.length, sample: quakes.slice(0, 3) });

